class APIScript{constructor(){}xhr(e,r){fetch(e).then(n=>{if(n['o'+'k'])return n[`${'js'+'on'}`]();throw new Error("Err")}).then(a=>{r(a)}).catch(c=>{console['e'+'rror']("Err:",c)})}fetchAnilist(e,r,t){e={id:parseInt(e),type:r.toUpperCase()};fetch(atob("aHR0cHM6Ly9ncmFwaHFsLmFuaWxpc3QuY28="),{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({query:`query (${'id'}: Int, ${'type'}: MediaType) {Media(id: $id, type: $type) {id idMal title {romaji english native userPreferred} description(asHtml: false) startDate {year month day} endDate {year month day} season seasonYear episodes duration status chapters volumes genres isAdult averageScore meanScore popularity favourites synonyms studios {edges {node {id name}}} source trailer {id site thumbnail} updatedAt coverImage {extraLarge large medium color} bannerImage format rankings {id rank type format year season allTime context} tags {id name description rank isMediaSpoiler isGeneralSpoiler userId} characters(sort: [ROLE, RELEVANCE, ID]) {edges {node {id name {full native} image {large}} role voiceActors(language: JAPANESE) {id name {full} image {large}}}} staff {edges {node {id name {full} image {large}} role}} reviews {edges {node {id summary rating score user {id name}}}} recommendations {edges {node {mediaRecommendation {id title {romaji english native} coverImage {large}}}}} externalLinks {id url site} streamingEpisodes {title thumbnail url site}}}`,variables:e})}).then(d=>d.json()).then(n=>{n.errors?console.error("AniErr:",n.errors):t(n)}).catch(g=>{console.error("ErrAni:",g)})}fetchJikan(e,r,t){this.xhr(`https://api.jikan.moe/v4/${r}/${e}/full`,t)}fetchTMDBMovie(e,r,t){this.xhr(`https://api.themoviedb.org/3/movie/${e}?api_key=`+r,t)}fetchTMDBMovieVideo(e,r,t){this.xhr(`https://api.themoviedb.org/3/movie/${e}/videos?api_key=`+r,t)}fetchTMDBTVSeries(e,r,t){this.xhr(`https://api.themoviedb.org/3/tv/${e}?api_key=`+r,t)}fetchTMDBTVSeriesVideo(e,r,t,i){this.xhr(`https://api.themoviedb.org/3/tv/${e}/season/${r}/videos?api_key=`+t,i)}}
